@js:

re = /\$\('#booktxthtml'\).html\((x[^)]+\))/


html = result.match(re)[1]

function x(encryptedData, key, iv) {
 ciphertext = java.base64DecodeToByteArray(encryptedData);
 ivBytes = java.base64DecodeToByteArray(iv);
 keyBytes = java.strToBytes(key);
 decrypted = java.createSymmetricCrypto(
    "aes/cbc/ZeroPadding", 
    keyBytes,
	   ivBytes
).decryptStr(ciphertext)
 return decrypted;
}
eval(html)

